import{_ as e,a as t,c as r,ac as i}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"Git工作区、协作与故障恢复","description":"三棵树、差异、身份、分支整合、冲突、拒绝推送及恢复边界。","frontmatter":{"title":"Git工作区、协作与故障恢复","description":"三棵树、差异、身份、分支整合、冲突、拒绝推送及恢复边界。","showdocs":{"topics":[{"id":"git","title":"Git","link":"/topics/git/"},{"id":"engineering","title":"编辑器与 IDE","link":"/topics/engineering/"}],"kind":"Git上手与对象","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Git：提交、分支与恢复","summary":"三棵树、差异、身份、分支整合、冲突、拒绝推送及恢复边界。","status":"active","related":[{"title":"Git Cherry-pick 指定提交同步指南","link":"/tools/git/practice/cherry-pick","kind":"Git完整实践与解答","scope":"general","audience":"general"},{"title":"Git Revert 撤销指定提交指南","link":"/tools/git/guide/git-revert","kind":"Git上手与对象","scope":"general","audience":"general"},{"title":"Git 分支与工作区","link":"/tools/git/reference/git-branches-general-general","kind":"Git任务与配置","scope":"general","audience":"general"},{"title":"Git 合并与撤销","link":"/tools/git/reference/git-merge-general-general","kind":"Git任务与配置","scope":"general","audience":"general"},{"title":"Git 提交、历史与配置","link":"/tools/git/reference/git-history-general-general","kind":"Git任务与配置","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Git：完整实践与解答","link":"/tools/git/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Git：完整实践与解答","link":"/tools/git/practice/application"}},"headers":[],"relativePath":"tools/git/daily-workflow-and-recovery.md","filePath":"tools/git/daily-workflow-and-recovery.md"}'),s={name:"tools/git/daily-workflow-and-recovery.md"};function n(o,a,l,p,h,c){return t(),r("div",null,[...a[0]||(a[0]=[i(`<h1 id="git工作区、协作与故障恢复" tabindex="-1">Git工作区、协作与故障恢复 <a class="header-anchor" href="#git工作区、协作与故障恢复" aria-label="Permalink to &quot;Git工作区、协作与故障恢复&quot;">​</a></h1><h2 id="part-1" tabindex="-1">检查状态、差异与提交身份 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;检查状态、差异与提交身份 {#part-1}&quot;">​</a></h2><p>需能区分工作区、暂存区和提交。先按当前状态选择<a href="#part-4">合并冲突处理</a>、<a href="#part-5">推送拒绝排查</a>或<a href="/tools/git/practice/application#source">本地提交练习</a>；练习使用支持 <code>--initial-branch</code> 的 Git 与 POSIX shell，在独立目录创建两次提交，不连接远端。 示例未在本轮执行。</p><h3 id="part-1-three-trees" tabindex="-1">Git 三棵树 <a class="header-anchor" href="#part-1-three-trees" aria-label="Permalink to &quot;Git 三棵树 {#part-1-three-trees}&quot;">​</a></h3><p>工作区保存当前文件，暂存区保存下一次提交的快照，HEAD指向当前提交。编辑后不暂存的行不会进入普通commit；先区分这三份状态，再决定比较或恢复哪一份。</p><h3 id="part-1-diff" tabindex="-1">Git 差异比较 <a class="header-anchor" href="#part-1-diff" aria-label="Permalink to &quot;Git 差异比较 {#part-1-diff}&quot;">​</a></h3><p>普通diff比较工作区与暂存区，diff --cached比较暂存区与HEAD。若文件同时有暂存和未暂存修改，两次比较都会出现；不能把空的普通diff当作没有待提交修改。</p><h3 id="part-1-identity" tabindex="-1">Git 身份配置 <a class="header-anchor" href="#part-1-identity" aria-label="Permalink to &quot;Git 身份配置 {#part-1-identity}&quot;">​</a></h3><p>提交身份是提交元数据，远端认证是访问权限。仓库local配置可以覆盖global身份；共享机器不把个人邮箱写入仓库模板，SSH密钥和HTTPS令牌也不等于user.name。</p><p><span id="part-3-sources"></span></p><p><span id="part-2-sources"></span></p><h3 id="part-1-sources" tabindex="-1">依据与适用范围 <a class="header-anchor" href="#part-1-sources" aria-label="Permalink to &quot;依据与适用范围 {#part-1-sources}&quot;">​</a></h3><ul><li><a href="https://git-scm.com/docs/git-reset" target="_blank" rel="noopener noreferrer">本课官方依据</a>，资料核对日2026-10-17。</li></ul><p>以上依据用于解释本文列明的规则；示例未执行，不代表产品全部能力或跨平台验证。历史资料的版本、账号与界面位置需按目标环境确认。</p><h2 id="part-2" tabindex="-1">选择分支与整合方式 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;选择分支与整合方式 {#part-2}&quot;">​</a></h2><h3 id="part-2-branch" tabindex="-1">Git 分支引用 <a class="header-anchor" href="#part-2-branch" aria-label="Permalink to &quot;Git 分支引用 {#part-2-branch}&quot;">​</a></h3><p>分支引用指向提交，创建分支不复制全部文件。切换分支可能更新工作区；未提交改动若与目标冲突会阻止切换。先保留修改，再选择新分支承接工作，不把分支名当备份文件。</p><h3 id="part-2-integration" tabindex="-1">Git 合并与变基 <a class="header-anchor" href="#part-2-integration" aria-label="Permalink to &quot;Git 合并与变基 {#part-2-integration}&quot;">​</a></h3><p>merge保留分叉并连接两条历史，rebase把提交重放到新基底，通常产生新的提交标识。已共享历史需要协作约定；选择取决于历史语义而非图是否好看。</p><h3 id="part-2-pick" tabindex="-1">Git cherry-pick 顺序 <a class="header-anchor" href="#part-2-pick" aria-label="Permalink to &quot;Git cherry-pick 顺序 {#part-2-pick}&quot;">​</a></h3><p>cherry-pick按补丁重放选定提交，不自动带上所有前置依赖。若B依赖A，应先A后B并核对目标分支是否已包含等价修改。冲突时继续前必须审阅最终差异，不能只删冲突标记。</p><h2 id="part-3" tabindex="-1">处理冲突、恢复与拒绝推送 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;处理冲突、恢复与拒绝推送 {#part-3}&quot;">​</a></h2><h3 id="part-3-conflict" tabindex="-1">Git 合并冲突处理 <a class="header-anchor" href="#part-3-conflict" aria-label="Permalink to &quot;Git 合并冲突处理 {#part-3-conflict}&quot;">​</a></h3><p>合并冲突表示同一结果无法自动决定，并不表示任一边必然正确。逐块理解共同祖先与双方目的，保留需要的业务语义，再暂存解决结果。未完成时使用对应merge或cherry-pick的abort，不能混用流程。</p><h3 id="part-3-reset" tabindex="-1">Git reset 恢复边界 <a class="header-anchor" href="#part-3-reset" aria-label="Permalink to &quot;Git reset 恢复边界 {#part-3-reset}&quot;">​</a></h3><p>reset --soft移动当前分支而保留暂存区和工作区；mixed还重置暂存区；hard会覆盖工作区并可能覆盖妨碍写入的未跟踪路径。先独立备份再选择，revert更适合需要保留共享历史的反向修改。</p><h3 id="part-3-rejected" tabindex="-1">Git non-fast-forward <a class="header-anchor" href="#part-3-rejected" aria-label="Permalink to &quot;Git non-fast-forward {#part-3-rejected}&quot;">​</a></h3><p>non-fast-forward说明远端目标不是本地提交的祖先，需要先获取并检查分叉。权限拒绝属于认证或授权问题，不能用强制推送解决。即使用force-with-lease也要理解预期远端引用与协作边界。</p><h3 id="part-3-legacy-notes-diagnostic-cases" tabindex="-1">代理、忽略、对象与子模块的排错分流 <a class="header-anchor" href="#part-3-legacy-notes-diagnostic-cases" aria-label="Permalink to &quot;代理、忽略、对象与子模块的排错分流 {#part-3-legacy-notes-diagnostic-cases}&quot;">​</a></h3><p>Git 代理拒绝和受保护分支如何分别排错？旧环境出现 Failed to connect to 127.0.0.1 port 1080，先用 git config --show-origin --get-regexp &#39;.*proxy&#39; 查来源及作用域，再核对代理进程和端口。确认不再需要该 global http.proxy 时才 unset；全局修改影响其他仓库，取消代理不能修复必须经代理访问的网络。</p><p>文件持续被忽略时，核对 core.excludesFile 返回的路径，再用 git check-ignore -v &lt;path&gt; 定位具体规则；历史机器的 .gitignore_global 只是一个配置实例。fetch first / non-fast-forward 需要 fetch 后检查分叉，受保护分支的 pre-receive hook declined 则由托管策略决定；这两类故障均不能靠清空历史绕过。</p><p>对象存储异常先保留仓库副本与完整错误，再用 git fsck --full 和 git log --oneline --decorate --all 分别检查完整性与可达历史。旧记录没有足够证据判断损坏原因，直接删对象文件的建议已撤回。</p><p>子模块 api already exists in the index 怎么判断？添加子模块遇到 &#39;api&#39; already exists in the index，先辨认普通目录、既有子模块和残留索引。只有确认要转换并保存原内容后，才移除该路径索引记录、把原目录移至已核对备份，再按真实地址 submodule add，sync 与 update --init。--cached 保留工作区但会改变提交跟踪方式，不等于无副作用。原拼写 submodoule 已撤回；本节没有执行任何转换。</p><h2 id="part-4" tabindex="-1">Git 合并冲突 <a class="header-anchor" href="#part-4" aria-label="Permalink to &quot;Git 合并冲突 {#part-4}&quot;">​</a></h2><p>定位冲突文件，逐处确认保留的内容，再完成合并。</p><p>适用于 merge 已停在冲突状态的分支。先确认当前分支和未提交改动；冲突标记两侧都可能包含必须保留的业务逻辑，不能机械地只选一边。</p><h3 id="part-4-排查步骤" tabindex="-1">排查步骤 <a class="header-anchor" href="#part-4-排查步骤" aria-label="Permalink to &quot;排查步骤 {#part-4-排查步骤}&quot;">​</a></h3><h4 id="part-4-_1-列出尚未解决的文件" tabindex="-1">1. 列出尚未解决的文件 <a class="header-anchor" href="#part-4-_1-列出尚未解决的文件" aria-label="Permalink to &quot;1. 列出尚未解决的文件 {#part-4-_1-列出尚未解决的文件}&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git status --short</span></span>
<span class="line"><span>git diff --name-only --diff-filter=U</span></span></code></pre></div><p><strong>预期结果:</strong> 输出仅包含待处理文件；记录当前分支，避免改错分支。</p><h4 id="part-4-_2-逐处阅读冲突区域" tabindex="-1">2. 逐处阅读冲突区域 <a class="header-anchor" href="#part-4-_2-逐处阅读冲突区域" aria-label="Permalink to &quot;2. 逐处阅读冲突区域 {#part-4-_2-逐处阅读冲突区域}&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git diff -- &lt;file&gt;</span></span></code></pre></div><p><strong>预期结果:</strong> 结合上下文理解双方改动，在编辑器中处理 &lt;&lt;&lt;&lt;&lt;&lt;&lt;、=======、&gt;&gt;&gt;&gt;&gt;&gt;&gt; 标记。</p><h4 id="part-4-_3-暂存并完成合并" tabindex="-1">3. 暂存并完成合并 <a class="header-anchor" href="#part-4-_3-暂存并完成合并" aria-label="Permalink to &quot;3. 暂存并完成合并 {#part-4-_3-暂存并完成合并}&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git add &lt;file&gt;</span></span>
<span class="line"><span>git status --short</span></span>
<span class="line"><span>git merge --continue</span></span></code></pre></div><p><strong>预期结果:</strong> 所有冲突文件均已解决后，合并继续；再运行项目测试验证最终组合。</p><h3 id="part-4-常见报错" tabindex="-1">常见报错 <a class="header-anchor" href="#part-4-常见报错" aria-label="Permalink to &quot;常见报错 {#part-4-常见报错}&quot;">​</a></h3><h4 id="part-4-unmerged-paths" tabindex="-1">Unmerged paths <a class="header-anchor" href="#part-4-unmerged-paths" aria-label="Permalink to &quot;Unmerged paths {#part-4-unmerged-paths}&quot;">​</a></h4><p><strong>原因:</strong> 文件仍有未解决的冲突，或修改后还未暂存。</p><p><strong>处理方式:</strong> 检查冲突标记，确认内容后 git add；再次查看 git status。</p><h4 id="part-4-merge-head-exists" tabindex="-1">MERGE_HEAD exists <a class="header-anchor" href="#part-4-merge-head-exists" aria-label="Permalink to &quot;MERGE_HEAD exists {#part-4-merge-head-exists}&quot;">​</a></h4><p><strong>原因:</strong> 前一次合并仍未结束。</p><p><strong>处理方式:</strong> 先用 git status 确认状态；继续解决并 merge --continue，或确认后用 git merge --abort 放弃本次合并。</p><h3 id="part-4-相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#part-4-相关文档" aria-label="Permalink to &quot;相关文档 {#part-4-相关文档}&quot;">​</a></h3><ul><li><a href="/tools/git/reference/git-history-general-general#entry-git-status-3fd29b5c3f">git status</a></li><li><a href="/tools/git/reference/git-merge-general-general#entry-git-merge-4cb00f6e1e">git merge</a></li></ul><h3 id="part-4-官方资料" tabindex="-1">官方资料 <a class="header-anchor" href="#part-4-官方资料" aria-label="Permalink to &quot;官方资料 {#part-4-官方资料}&quot;">​</a></h3><ul><li><a href="https://git-scm.com/docs/git-merge" target="_blank" rel="noopener noreferrer">https://git-scm.com/docs/git-merge</a></li><li><a href="https://git-scm.com/docs/git-status" target="_blank" rel="noopener noreferrer">https://git-scm.com/docs/git-status</a></li></ul><h2 id="part-5" tabindex="-1">Git 推送被拒绝 <a class="header-anchor" href="#part-5" aria-label="Permalink to &quot;Git 推送被拒绝 {#part-5}&quot;">​</a></h2><p>确认远端新增提交与权限问题，再同步分支。</p><p>先区分 non-fast-forward 与认证失败。共享分支有新提交时，先获取并审查远端历史；不要直接强制推送覆盖他人工作。</p><h3 id="part-5-排查步骤" tabindex="-1">排查步骤 <a class="header-anchor" href="#part-5-排查步骤" aria-label="Permalink to &quot;排查步骤 {#part-5-排查步骤}&quot;">​</a></h3><h4 id="part-5-_1-确认分支与上游" tabindex="-1">1. 确认分支与上游 <a class="header-anchor" href="#part-5-_1-确认分支与上游" aria-label="Permalink to &quot;1. 确认分支与上游 {#part-5-_1-确认分支与上游}&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git status -sb</span></span>
<span class="line"><span>git branch -vv</span></span></code></pre></div><p><strong>预期结果:</strong> 看到当前分支、上游和本地是否有未提交改动。</p><h4 id="part-5-_2-比较本地与远端提交" tabindex="-1">2. 比较本地与远端提交 <a class="header-anchor" href="#part-5-_2-比较本地与远端提交" aria-label="Permalink to &quot;2. 比较本地与远端提交 {#part-5-_2-比较本地与远端提交}&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git fetch origin</span></span>
<span class="line"><span>git log --oneline --left-right HEAD...origin/&lt;branch&gt;</span></span></code></pre></div><p><strong>预期结果:</strong> 左右两侧标记显示各自独有的提交，能判断是否需要整合远端更新。</p><h4 id="part-5-_3-整合后重试推送" tabindex="-1">3. 整合后重试推送 <a class="header-anchor" href="#part-5-_3-整合后重试推送" aria-label="Permalink to &quot;3. 整合后重试推送 {#part-5-_3-整合后重试推送}&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git merge origin/&lt;branch&gt;</span></span>
<span class="line"><span>git push origin &lt;branch&gt;</span></span></code></pre></div><p><strong>预期结果:</strong> 先解决可能的合并冲突并运行测试；推送成功后远端包含双方提交。</p><h3 id="part-5-常见报错" tabindex="-1">常见报错 <a class="header-anchor" href="#part-5-常见报错" aria-label="Permalink to &quot;常见报错 {#part-5-常见报错}&quot;">​</a></h3><h4 id="part-5-non-fast-forward" tabindex="-1">non-fast-forward <a class="header-anchor" href="#part-5-non-fast-forward" aria-label="Permalink to &quot;non-fast-forward {#part-5-non-fast-forward}&quot;">​</a></h4><p><strong>原因:</strong> 远端分支包含本地没有的提交。</p><p><strong>处理方式:</strong> 先 fetch 并比较历史，再按团队约定 merge 或 rebase；不要直接 force push。</p><h4 id="part-5-permission-denied" tabindex="-1">Permission denied <a class="header-anchor" href="#part-5-permission-denied" aria-label="Permalink to &quot;Permission denied {#part-5-permission-denied}&quot;">​</a></h4><p><strong>原因:</strong> 账号、凭据或仓库写入权限不匹配。</p><p><strong>处理方式:</strong> 确认 remote URL、当前身份和仓库权限；修复认证后重试，合并历史不会解决权限问题。</p><h3 id="part-5-相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#part-5-相关文档" aria-label="Permalink to &quot;相关文档 {#part-5-相关文档}&quot;">​</a></h3><ul><li><a href="/tools/git/reference/git-remote-general-general#entry-git-push-d1094f5d58">git push</a></li></ul><h3 id="part-5-官方资料" tabindex="-1">官方资料 <a class="header-anchor" href="#part-5-官方资料" aria-label="Permalink to &quot;官方资料 {#part-5-官方资料}&quot;">​</a></h3><ul><li><a href="https://git-scm.com/docs/git-push" target="_blank" rel="noopener noreferrer">https://git-scm.com/docs/git-push</a></li><li><a href="https://git-scm.com/docs/git-fetch" target="_blank" rel="noopener noreferrer">https://git-scm.com/docs/git-fetch</a></li></ul>`,81)])])}const u=e(s,[["render",n]]);export{g as __pageData,u as default};
